#include <GL/glew.h>
#include <windows.h>
#include <glm/glm.hpp>
#include <glm/gtc/matrix_transform.hpp>
#include <cstdlib>
#include <cmath>
#include <iostream>
#include <vector>
#include <string>
#include "fade-shaders.inc"
int checks;
void check(bool yes,const char* m){++checks;if(!yes){std::cerr<<"FAIL: "<<m<<"\n";std::exit(1);}}
void context(){WNDCLASSW wc{};wc.lpfnWndProc=DefWindowProcW;wc.hInstance=GetModuleHandleW(nullptr);wc.lpszClassName=L"CMFadeTest";RegisterClassW(&wc);auto w=CreateWindowW(wc.lpszClassName,L"CM production raster tests",WS_OVERLAPPEDWINDOW,0,0,32,32,nullptr,nullptr,wc.hInstance,nullptr);check(w,"hidden context window");auto dc=GetDC(w);PIXELFORMATDESCRIPTOR p{};p.nSize=sizeof(p);p.nVersion=1;p.dwFlags=PFD_DRAW_TO_WINDOW|PFD_SUPPORT_OPENGL;p.iPixelType=PFD_TYPE_RGBA;p.cColorBits=32;p.cDepthBits=24;auto pf=ChoosePixelFormat(dc,&p);check(pf&&SetPixelFormat(dc,pf,&p),"pixel format");auto rc=wglCreateContext(dc);check(rc&&wglMakeCurrent(dc,rc),"WGL context");glewExperimental=GL_TRUE;check(glewInit()==GLEW_OK,"GL entries");while(glGetError()!=GL_NO_ERROR){}}
GLuint program(const char* vs,const char* fs){auto compile=[](GLenum k,const char* text){auto s=glCreateShader(k);glShaderSource(s,1,&text,nullptr);glCompileShader(s);GLint ok;glGetShaderiv(s,GL_COMPILE_STATUS,&ok);if(!ok){char log[8192];glGetShaderInfoLog(s,sizeof(log),nullptr,log);std::cerr<<log;std::exit(2);}return s;};auto v=compile(GL_VERTEX_SHADER,vs),f=compile(GL_FRAGMENT_SHADER,fs),p=glCreateProgram();glAttachShader(p,v);glAttachShader(p,f);glBindAttribLocation(p,0,"in_pos");glBindAttribLocation(p,1,"in_base");glLinkProgram(p);GLint ok;glGetProgramiv(p,GL_LINK_STATUS,&ok);check(ok,"actual production scene shaders link");return p;}
int main(){context();PipelineShader settings;auto vertex=VertexSource(true,true).generate(),fragment=FragmentShaderSource(&settings).generate();auto p=program(vertex.c_str(),fragment.c_str());check(glGetUniformLocation(p,"vrNativeRaster")>=0,"production shader assembly exposes original-raster Fade");
 GLuint fbo,tex,depth,vao,vbo;glGenFramebuffers(1,&fbo);glBindFramebuffer(GL_FRAMEBUFFER,fbo);glGenTextures(1,&tex);glBindTexture(GL_TEXTURE_2D,tex);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,1024,1024,0,GL_RGBA,GL_UNSIGNED_BYTE,nullptr);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,tex,0);glGenRenderbuffers(1,&depth);glBindRenderbuffer(GL_RENDERBUFFER,depth);glRenderbufferStorage(GL_RENDERBUFFER,GL_DEPTH_COMPONENT24,1024,1024);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_RENDERBUFFER,depth);check(glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE,"scene color/depth FBO");glViewport(0,0,1024,1024);glGenVertexArrays(1,&vao);glBindVertexArray(vao);glGenBuffers(1,&vbo);glBindBuffer(GL_ARRAY_BUFFER,vbo);glVertexAttribPointer(0,4,GL_FLOAT,GL_FALSE,4*sizeof(float),0);glEnableVertexAttribArray(0);glVertexAttrib4f(1,.8f,.6f,.4f,.7f);glEnable(GL_DEPTH_TEST);glDepthFunc(GL_ALWAYS);
 auto render=[&](bool fade,bool hud=false,float zoom=1.f,float eye=0.f){glUseProgram(p);auto identity=glm::mat4(1),vp=glm::ortho(-2.f,2.f,-1.5f,1.5f,.01f,100.f)*glm::translate(glm::mat4(1),glm::vec3(-eye,0,0));glUniformMatrix4fv(glGetUniformLocation(p,"ndcMat"),1,GL_FALSE,&identity[0][0]);glUniformMatrix4fv(glGetUniformLocation(p,"vrMat"),1,GL_FALSE,&vp[0][0]);glUniform2f(glGetUniformLocation(p,"vrTan"),1,.75f);glUniform4f(glGetUniformLocation(p,"vrOverlay"),2,1.5f,1,1);glUniform3f(glGetUniformLocation(p,"vrComfort"),0,0,0);glUniform1f(glGetUniformLocation(p,"vrHudSize"),1);glUniform1f(glGetUniformLocation(p,"vrWorldZoom"),zoom);glUniform3f(glGetUniformLocation(p,"vrNativeRaster"),.5f,.375f,fade?1.f:0.f);float z=hud?1.f:.5f;float xy=hud?1.f:1.05f;float data[]={-xy,-xy,z,1,xy,-xy,z,1,-xy,xy,z,1,xy,xy,z,1};glBufferData(GL_ARRAY_BUFFER,sizeof(data),data,GL_STREAM_DRAW);glClearColor(0,0,0,0);glClearDepth(1);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);glDrawArrays(GL_TRIANGLE_STRIP,0,4);std::vector<unsigned char> pixels(1024*1024*4);glReadPixels(0,0,1024,1024,GL_RGBA,GL_UNSIGNED_BYTE,pixels.data());return pixels;};
 auto normal=render(false),faded=render(true);auto at=[](const auto& a,int x,int y,int c=0){return a[(y*1024+x)*4+c];};
 bool same=true;for(int y=256;y<768;y++)for(int x=256;x<768;x++)for(int c=0;c<4;c++)same&=at(normal,x,y,c)==at(faded,x,y,c);check(same,"every original interior pixel remains byte-identical");
 check(at(faded,800,512)>0&&at(faded,800,512)<at(normal,800,512),"extra scenery darkens smoothly beyond native edge");check(at(faded,900,512)==0&&at(faded,512,900)==0,"quarter-raster outer border reaches black horizontally and vertically");check(at(faded,832,832)<at(faded,832,512),"rounded corner uses joint outside distance");
 bool alpha=true;for(size_t i=3;i<normal.size();i+=4)alpha&=normal[i]==faded[i];check(alpha,"Fade preserves original scene alpha");
 std::vector<float> baselineDepth(1024*1024),fadeDepth(1024*1024);render(false);glReadPixels(0,0,1024,1024,GL_DEPTH_COMPONENT,GL_FLOAT,baselineDepth.data());render(true);glReadPixels(0,0,1024,1024,GL_DEPTH_COMPONENT,GL_FLOAT,fadeDepth.data());check(baselineDepth==fadeDepth,"Fade preserves all production scene depth values");
 check(render(false,true)==render(true,true),"native HUD/reticle overlay never inherits Fade even outside border");check(render(false)==normal,"next eye/frame disabling Fade restores exact original raster");
 for(float eye:{-.032f,.032f}){auto a=render(false,false,1,eye),b=render(true,false,1,eye);check(at(a,512,512)==at(b,512,512)&&at(b,900,512)==0,"both eye transforms preserve native interior and fade outside");}
 auto zoomOff=render(false,false,2),zoomFade=render(true,false,2);check(at(zoomOff,900,512)==at(zoomFade,900,512),"Game zoom magnifies native interior together with scene");
 check(glGetError()==GL_NO_ERROR,"actual scene GLSL raster checks have no GL errors");std::cout<<checks<<" production scene Fade raster/depth checks passed\n";
}
